import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.DC2anBTf.js";const p=JSON.parse('{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1793595620000}'),d={name:"changelog.md"};function i(l,e,n,s,c,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><p>本页与仓库根 <a href="https://github.com/MengXi-Studio/unix-architecture/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a> 保持同步。</p><h2 id="_1-1-0-2026-11-02" tabindex="-1">[1.1.0] - 2026-11-02 <a class="header-anchor" href="#_1-1-0-2026-11-02" aria-label="Permalink to &quot;[1.1.0] - 2026-11-02&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>UI 组件库集成</strong>（<code>uni_modules/m-ui-x</code> v0.1.0）：11 个基础组件 easycom 零注册接入；主题经根 <code>uni.scss</code> 定义 <code>$m-*</code> 变量编译期覆盖（禁 <code>@import</code> vars.scss，防 sass 循环导入）。</li><li><strong>页面消费替换</strong>：登录页 / 首页按钮替换为 <code>m-button</code>（loading 态绑定 useLoading、danger-plain-hairline 语义形态）。</li><li><strong>ux-router 0.8.2 <code>backFallback</code> 接入</strong>：back() 页面栈不足时兜底 relaunch 回首页（走完整守卫链）。</li><li><strong>文档站</strong>：VitePress 使用文档（本站），部署于 GitHub Pages。</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>ux-pinia 0.1.0 → 0.2.0 强制迁移</strong>（插件 setup 式 API 移除）：store 重写为 class 式 <code>UserStore extends PiniaStoreBase</code>（state <code>reactive&lt;T&gt;</code> 包裹、action method 化、constructor <code>bindState</code>）；<code>storeToRefs</code> / <code>.value</code> 访问改为 <code>store.state.字段</code> 直读。</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>发行打包修复</strong>：uts 插件入口导出字符串常量在 5.34 发行流水线生成非法 JS（9 个无消费方常量去导出规避）；app-android 发行拷贝不追踪 <code>export type ... from</code> 转发链（域类型收敛 types.uts 单文件）；Android 云打包 Kotlin 编译修复（显式泛型、guardRoute 显式实参、m-loading 规避 5.34 生成器缺陷）。</li></ul><h3 id="verified" tabindex="-1">Verified <a class="header-anchor" href="#verified" aria-label="Permalink to &quot;Verified&quot;">​</a></h3><ul><li>Web 端登录闭环 E2E；Android 云打包编译通过（Kotlin 链路）。</li><li>Android 云打包产物（APK）：<code>__UNI__FDA7014</code>——<a href="https://mp-b8b8347a-48e9-434d-8302-3e9d99c2cb01.cdn.bspapp.com/cloudstorage/app-build-pkg/1793535799767-__UNI__FDA7014_1793535789282.apk" target="_blank" rel="noreferrer">https://mp-b8b8347a-48e9-434d-8302-3e9d99c2cb01.cdn.bspapp.com/cloudstorage/app-build-pkg/1793535799767-__UNI__FDA7014_1793535789282.apk</a>（uniCloud 云存储直链，有时效性，过期请在 HBuilderX 重新云打包）。</li></ul><h2 id="_1-0-0-2026-10-21" tabindex="-1">[1.0.0] - 2026-10-21 <a class="header-anchor" href="#_1-0-0-2026-10-21" aria-label="Permalink to &quot;[1.0.0] - 2026-10-21&quot;">​</a></h2><p>工程架构从零搭建至首个稳定形态：api / stores / router / utils / pages 全分层落地，Web 端全链路验证通过。含分层骨架、网络层封装（双拦截器）、鉴权体系（内存缓存 + ensureAuthReady）、全局守卫（白名单 + 冷启动补跑 + InterceptorPlugin 兜底）、类型组织体系、ux-utils 接入、AI 协作规则体系（.trae）。</p><p>完整记录见仓库 <a href="https://github.com/MengXi-Studio/unix-architecture/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a>。</p>',14)])])}const g=a(d,[["render",i]]);export{p as __pageData,g as default};
